import React, { useState, useEffect } from 'react';

const Navbar = () => {
  const [activeSection, setActiveSection] = useState('');

  useEffect(() => {
    const handleScroll = () => {
      const sections = ['about', 'experience', 'skills', 'projects', 'contact'];
      const scrollPosition = window.scrollY;

      sections.forEach(section => {
        const element = document.getElementById(section);
        if (element) {
          const offset = element.offsetTop - 100; // Adjust for navbar height
          if (scrollPosition >= offset) {
            setActiveSection(section);
          }
        }
      });
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className="bg-gray-800 text-white p-4 sticky top-0 z-10 transition-colors duration-300">
      <div className="container mx-auto flex justify-between items-center">
        <h1 className="text-xl font-bold text-gray-100 hover:text-white transition-colors duration-200">[Your Name]</h1>
        <ul className="flex space-x-6 list-none">
          <li>
            <a
              href="#about"
              className={`hover:text-blue-300 transition-colors duration-200 ${activeSection === 'about' ? 'text-blue-400 border-b-2 border-blue-400' : ''}`}
            >
              About
            </a>
          </li>
          <li>
            <a
              href="#experience"
              className={`hover:text-blue-300 transition-colors duration-200 ${activeSection === 'experience' ? 'text-blue-400 border-b-2 border-blue-400' : ''}`}
            >
              Experience
            </a>
          </li>
          <li>
            <a
              href="#skills"
              className={`hover:text-blue-300 transition-colors duration-200 ${activeSection === 'skills' ? 'text-blue-400 border-b-2 border-blue-400' : ''}`}
            >
              Skills
            </a>
          </li>
          <li>
            <a
              href="#projects"
              className={`hover:text-blue-300 transition-colors duration-200 ${activeSection === 'projects' ? 'text-blue-400 border-b-2 border-blue-400' : ''}`}
            >
              Projects
            </a>
          </li>
          <li>
            <a
              href="#contact"
              className={`hover:text-blue-300 transition-colors duration-200 ${activeSection === 'contact' ? 'text-blue-400 border-b-2 border-blue-400' : ''}`}
            >
              Contact
            </a>
          </li>
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
